FILES["interview-prep"] = `topic,text,options,correct,explanation,difficulty,tags
interview-prep,"Which structure is most effective when describing a production incident?","[""STAR, emphasising your specific actions and a measurable result"", ""A chronological account of everything that happened"", ""A technical deep dive on the root cause only"", ""A blame-focused account of other teams"""]",0,"STAR gives the interviewer a predictable structure so they can follow your decision points. Spend the most time on Action, since that is what they assess, and close with a quantified Result and what you changed afterwards. A chronological recount buries the decisions, and technical-only leaves them unable to judge how you operate under pressure.",EASY,behavioural
interview-prep,"What makes a strong answer to 'tell me about a time you disagreed with a decision'?","[""You raised the concern with evidence, respected the outcome, and committed to measuring it"", ""You disagreed, were overruled, and quietly did it your own way"", ""You waited until after it shipped to object"", ""You escalated to your manager straight away"""]",0,"Interviewers are assessing whether you raise concerns with evidence and can commit once a decision is made. Quietly doing it your own way is far worse than disagreeing, and immediate escalation reads as political. The follow-up they listen for is what you did next: helped measure the outcome, or kept arguing.",MEDIUM,behavioural
interview-prep,"How should you open a system design round?","[""Clarify requirements, scale, constraints and success criteria before proposing anything"", ""Propose your preferred architecture immediately to show expertise"", ""Start with the database choice since it is hardest"", ""Ask what stack they use and design around it"""]",0,"Requirements and constraints drive every later choice, and asking them signals you can size a system rather than guess. Saying your assumptions out loud lets the interviewer correct you early. Jumping to an architecture risks building the wrong system very convincingly.",MEDIUM,system-design
interview-prep,"What is a good answer to 'where do you see yourself in three years'?","[""A direction tied to the role, without demanding a specific title"", ""A specific job title you will have reached"", ""That you want to move into management"", ""That you are unsure and open to anything"""]",0,"A direction that builds on the role reads as committed and coachable, whereas demanding a title or declaring management ambition narrows you needlessly. Unsure and open suggests no drive. The interviewer wants to see your next step is contiguous with what they offer, so tie it to their actual problems.",MEDIUM,behavioural
interview-prep,"Why do interviewers ask about a failure you caused?","[""To see how you surface it, communicate it, and fix the class of problem rather than the instance"", ""To catch candidates with poor judgement"", ""Because they need someone to blame internally"", ""To see if you can hide a mistake"""]",0,"Everyone causes incidents; what separates senior engineers is the response. A good answer shows you noticed quickly, told stakeholders before they noticed, fixed the immediate problem, then made the failure class less likely through a review, alert or test. Listen for 'we' rather than 'they', and a systemic fix rather than a heroics story.",MEDIUM,incident
interview-prep,"What is the most credible first step to demonstrate DevOps capability when moving from development?","[""Owning one production service end to end, including pipeline, monitoring, alerts and on-call"", ""Collecting every available certification"", ""Contributing to open-source infrastructure tooling"", ""Completing a Kubernetes administrator course"""]",0,"Interviewers want evidence you have run systems, not studied them. Owning one service with real on-call responsibility and documented reliability outcomes is a far stronger signal than certifications, which prove attendance. Open-source work is also strong but slower to land.",MEDIUM,transition
interview-prep,"How should you answer about a gap such as never running multi-region failover?","[""State the gap honestly, describe the closest adjacent experience, and outline how you would approach it"", ""Avoid the question and highlight another strength"", ""Claim you have done it but keep it vague"", ""Say you would need training and stop there"""]",0,"Honesty plus a clear approach beats both a dodge and an overclaim. Interviewers assess judgement, and reasoning about an unsolved problem is a good signal. Overclaiming is the worst outcome, easy to probe and expensive if uncovered, and vagueness reads as evasive.",MEDIUM,deep-dive
interview-prep,"Which question signals genuine interest in a DevOps role?","[""How does the team handle a deployment when the on-call engineer is already in an incident?"", ""What is the tech stack?"", ""How many people are on the team?"", ""When is the next round?"""]",0,"This is specific, shows you already understand that reliability work overlaps incident response, and invites a real answer about process and tooling. The stack question gets you a list; the on-call question gets you the operating philosophy, which is what you are actually deciding on.",EASY,behavioural
interview-prep,"What is the most common mistake candidates make when describing system design trade-offs?","[""Presenting one architecture with no alternatives or reasoning, so there is nothing to discuss"", ""Choosing the wrong database"", ""Asking too many clarifying questions"", ""Ignoring cost entirely"""]",0,"Design interviews are a conversation about trade-offs. Presenting a single design with no alternatives removes the discussion the interviewer is trying to have, and makes it impossible to tell whether you chose deliberately or by default. Offering two options with the trade-off between them demonstrates judgement directly.",MEDIUM,system-design
interview-prep,"In a STAR answer, what proportion of your time should go to describing your own actions?","[""The majority, because that is what the interviewer is assessing"", ""As little as possible, to focus on the team"", ""Half, split evenly with context"", ""None, since actions are usually obvious"""]",0,"Situation and Task are usually a sentence or two each. Action and Result take the remaining time, and Result should be quantified. Spending most of the answer on setup context is the most common way candidates lose an otherwise strong interview.",EASY,behavioural
`;

/**
 * Parses one CSV row by structure rather than by generic quote rules.
 *
 * The options column is a JSON array, and hand-authored CSV mixes `""` and `"`
 * inside it inconsistently. A generic RFC-4180 reader closes the field on the
 * first lone quote it meets inside the array and silently shifts every later
 * column, which is how an entire row gets dropped. Anchoring on the array
 * brackets instead removes that ambiguity.
 *
 * Expected shape:
 *   topic,"question","[""a"", ""b"""]",0,"explanation",DIFFICULTY,tags
 */
function parseRow(line: string): Record<string, string> | null {
  let i = 0;
  const skipSpace = () => {
    while (i < line.length && (line[i] === " " || line[i] === "\t")) i += 1;
  };

  const readUntilComma = (): string => {
    let out = "";
    while (i < line.length && line[i] !== ",") out += line[i++];
    return out.trim();
  };

  /** Reads a double-quoted field, honouring `""` as an escaped quote. */
  const readQuoted = (): string => {
    if (line[i] !== '"') return readUntilComma();
    i += 1;
    let out = "";
    while (i < line.length) {
      const char = line[i]!;
      if (char === '"') {
        if (line[i + 1] === '"') {
          out += '"';
          i += 2;
          continue;
        }
        i += 1;
        return out;
      }
      out += char;
      i += 1;
    }
    return out;
  };

  /**
   * Reads the JSON array in the options column. The array is itself wrapped in
   * CSV quotes, so an optional leading quote is consumed first and a matching
   * trailing one after the closing bracket.
   */
  const readOptionsArray = (): string => {
    if (line[i] === '"') i += 1; // CSV field opener
    const start = i;
    let depth = 0;
    let inQuotes = false;
    while (i < line.length) {
      const char = line[i]!;
      if (inQuotes) {
        if (char === "\\") {
          i += 2;
          continue;
        }
        if (char === '"') inQuotes = false;
      } else if (char === '"') inQuotes = true;
      else if (char === "[") depth += 1;
      else if (char === "]") {
        depth -= 1;
        if (depth === 0) {
          i += 1;
          break;
        }
      }
      i += 1;
    }
    const value = line.slice(start, i).trim();
    if (line[i] === '"') i += 1; // CSV field closer
    return value;
  };

  skipSpace();
  const topic = readUntilComma();
  if (i >= line.length) return null;
  i += 1; // consume comma

  skipSpace();
  const text = readQuoted();
  if (i >= line.length) return null;
  i += 1; // consume comma

  skipSpace();
  const options = readOptionsArray();
  if (i >= line.length) return null;
  i += 1; // consume comma

  skipSpace();
  const correct = readUntilComma();
  if (i >= line.length) return null;
  i += 1;

  skipSpace();
  const explanation = readQuoted();
  if (i < line.length) i += 1;

  const tail = line.slice(i);
  const [difficulty = "", tags = ""] = tail.split(",");

  return {
    topic,
    text: text.trim(),
    options,
    correct: correct.trim(),
    explanation: explanation.trim(),
    difficulty: difficulty.trim(),
    tags: tags.trim(),
  };
}

/** Parsed rows for the topic banks. */
function parseRows(csv: string): CsvQuestion[] {
  const lines = csv.split("\n").filter((l) => l.trim().length > 0);
  lines.shift(); // header
  const result: CsvQuestion[] = [];

  for (const line of lines) {
    const record = parseRow(line);
    if (!record) continue;

    const optionsField = record.options ?? "";
    let options: string[];
    try {
      // CSV doubles every quote, so undo that before parsing the JSON array.
      const parsed = JSON.parse(optionsField.replace(/""/g, '"'));
      options = Array.isArray(parsed) ? parsed.map(String) : [];
    } catch {
      options = [];
    }

    const correct = Number(record.correct ?? "");
    if (
      !record.text ||
      options.length < 2 ||
      !Number.isInteger(correct) ||
      correct < 0 ||
      correct >= options.length
    ) {
      continue;
    }

    const difficulty = (record.difficulty ?? "MEDIUM").toUpperCase();
    if (difficulty !== "EASY" && difficulty !== "MEDIUM" && difficulty !== "HARD") {
      continue;
    }

    result.push({
      topic: record.topic ?? "",
      text: record.text,
      options,
      correct,
      explanation: record.explanation ?? "",
      difficulty,
      tags: record.tags ?? "",
    });
  }

  return result;
}

/** Every question from the CSV blocks, grouped by topic slug. */
export function getContentVolume(): Record<string, CsvQuestion[]> {
  const grouped: Record<string, CsvQuestion[]> = {};

  for (const [topicSlug, csv] of Object.entries(FILES)) {
    grouped[topicSlug] = parseRows(csv.trim());
  }

  // The placeholder row exists only to keep the CSV column count consistent;
  // drop anything that is not real content.
  for (const [slug, rows] of Object.entries(grouped)) {
    grouped[slug] = rows.filter(
      (r) => !(r.tags ?? "").includes("unused") && r.explanation.length > 10,
    );
  }

  return grouped;
}
